import React, { useEffect, useState } from "react";

function MyAppointments() {
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("token");
    console.log("TOKEN:", token);

    if (!token) {
      alert("Please login first");
      return;
    }

    fetch("http://localhost:8081/api/appointments/my", {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then(async (res) => {
        console.log("STATUS:", res.status);

        const text = await res.text(); // 🔥 important debug step
        console.log("RAW RESPONSE:", text);

        if (!res.ok) throw new Error(text);

        return JSON.parse(text);
      })
      .then((data) => {
        console.log("DATA:", data);
        setAppointments(data);
      })
      .catch((err) => {
        console.error("ERROR:", err.message);
        alert("Error loading appointments ❌");
      });
  }, []);

  const cancelAppointment = (id) => {
    const token = localStorage.getItem("token");

    fetch(`http://localhost:8081/api/appointments/${id}/cancel`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })
      .then((res) => res.json())
      .then(() => {
        // update UI
        setAppointments((prev) =>
          prev.map((a) =>
            a.id === id ? { ...a, status: "CANCELLED" } : a
          )
        );
      })
      .catch((err) => console.error(err));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>My Appointments</h2>

      {appointments.length === 0 ? (
        <p>No appointments found</p>
      ) : (
        appointments.map((a) => (
          <div
            key={a.id}
            style={{
              border: "1px solid #ccc",
              margin: "10px 0",
              padding: "10px",
              borderRadius: "8px",
            }}
          >
            <p><b>Doctor:</b> {a.doctorName}</p>
            <p><b>Specialization:</b> {a.specialization}</p>
            <p><b>Date:</b> {a.appointmentDate}</p>
            <p><b>Time:</b> {a.timeSlot}</p>
            <p><b>Status:</b> {a.status}</p>

            {a.status === "BOOKED" && (
              <button
                onClick={() => cancelAppointment(a.id)}
                style={{
                  background: "red",
                  color: "#fff",
                  border: "none",
                  padding: "6px 10px",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>
            )}
          </div>
        ))
      )}
    </div>
  );
}

export default MyAppointments;
